"""Saved qualification receipts only; no tokenizer, model, solver or learner imports."""
import collections
import hashlib
import json
import math
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
ARTIFACT = ROOT / 'benchmarks/frozen_reader_qualification_v1.json'
FIXTURE = ROOT / 'experiments/r4_integrated/contextual_full_choice_train.json'
OUTPUT = ROOT / '.pytest-tmp/frozen-reader-outcome-audit.json'
SOURCE = '25689a9d2d97506591fe83a47f91a05ea37e2298'


def digest(path):
    with path.open('rb') as stream:
        return hashlib.file_digest(stream, 'sha256').hexdigest()


def decode(value):
    return None if value is None else bytes.fromhex(value).decode('utf-8', errors='strict')


def main():
    assert not OUTPUT.exists(), 'do not overwrite independent audit'
    report = json.loads(ARTIFACT.read_text(encoding='utf-8'))
    fixture = json.loads(FIXTURE.read_text(encoding='utf-8'))
    assert report['terminal'] == 'completed'
    assert report['source']['revision'] == SOURCE
    assert report['fixture_sha256'] == digest(FIXTURE)
    assert len(report['rows']) == 256
    tasks = {x['id']: x for x in fixture['tasks']}
    docs = {x['id']: x['text'].encode() for x in fixture['documents']}
    answers = {x['answer']: x for x in fixture['tasks'] if x['answer'] is not None}
    grouped = collections.defaultdict(list)
    semantic = []
    windows_checked = 0
    for row in report['rows']:
        task = tasks[row['case']]
        access, wording = row['group'].split(':')
        expected_query = task['query'] if wording == 'actual' else fixture['alternate_queries'][task['id']]
        assert row['query'] == expected_query
        expected = task['answer']
        assert decode(row['expected_hex']) == expected
        offered = [task['expected_source_id']] if access == 'known_source' else list(docs)
        assert row['offered_source_ids'] == offered
        read = row['reading']
        assert read['reader_sha256'] == report['reader_sha256']
        assert read['query_sha256'] == hashlib.sha256(expected_query.encode()).hexdigest()
        assert read['source_bytes'] == sum(len(docs[x]) for x in offered)
        assert read['window_count'] == len(read['windows'])
        assert read['paired_tokens'] == sum(x['paired_tokens'] for x in read['windows'])
        best = None
        tied = False
        for window in read['windows']:
            windows_checked += 1
            identity = decode(window['document_id_hex'])
            raw = docs[identity]
            assert identity == offered[window['document_index']]
            assert window['content_sha256'] == hashlib.sha256(raw).hexdigest()
            assert 0 <= window['context_byte_start'] < window['context_byte_end'] <= len(raw)
            assert window['paired_tokens'] <= 386 and window['context_tokens'] > 0
            assert 0 <= window['byte_start'] < window['byte_end'] <= len(raw)
            emitted = bytes.fromhex(window['emitted'])
            assert raw[window['byte_start']:window['byte_end']] == emitted
            assert window['best_margin'] == window['span_score'] - window['null_score']
            assert math.isfinite(window['best_margin'])
            if best is None or window['best_margin'] > best['best_margin']:
                best, tied = window, window['different_answer_tie']
            elif window['best_margin'] == best['best_margin']:
                tied |= window['different_answer_tie'] or window['emitted'] != best['emitted']
        reason = 'empty_evidence' if best is None else 'null_margin' if best['best_margin'] <= 0 else 'different_answer_tie' if tied else None
        assert read['stop_reason'] == reason
        assert read['stopped'] == (reason is not None)
        assert read['emitted'] == (None if reason else best['emitted'])
        assert read['selected'] == (None if reason else best)
        emitted = decode(read['emitted'])
        assert row['correct'] == (read['stopped'] if expected is None else emitted == expected)
        selected_source = None if reason else decode(best['document_id_hex'])
        if row['correct']:
            category = 'exact_answer' if expected is not None else 'correct_STOP'
        elif reason:
            category = 'supported_abstention'
        elif expected is None:
            category = 'unsupported_answer'
        elif emitted.strip() == expected:
            category = 'outer_whitespace_only'
        elif emitted in expected:
            category = 'partial_expected_answer'
        elif expected in emitted:
            category = 'overextended_expected_answer'
        elif emitted in answers:
            other = answers[emitted]
            category = 'same_entity_wrong_property' if other['entity'] == task['entity'] else 'other_entity_same_property' if other['property'] == task['property'] else 'other_entity_other_property'
        else:
            category = 'other_source_span'
        cuts_word = False
        if reason is None:
            raw = docs[selected_source]
            a, b = best['byte_start'], best['byte_end']
            left, middle, right = raw[:a].decode(), raw[a:b].decode(), raw[b:].decode()
            word = lambda c: c.isalnum() or c == '_'
            cuts_word = bool((left and middle and word(left[-1]) and word(middle[0])) or (right and middle and word(middle[-1]) and word(right[0])))
        item = {'group': row['group'], 'case': task['id'], 'query': expected_query, 'entity': task['entity'], 'property': task['property'], 'answer_words': task['answer_word_count'], 'expected': expected, 'emitted': emitted, 'correct': row['correct'], 'category': category, 'stop_reason': reason, 'selected_source': selected_source, 'expected_source': task['expected_source_id'], 'wrong_source': selected_source is not None and selected_source != task['expected_source_id'], 'cuts_word_boundary': cuts_word, 'best_margin': read['best_margin'], 'best_even_if_STOP': decode(best['emitted']), 'best_source_even_if_STOP': decode(best['document_id_hex'])}
        semantic.append(item)
        grouped[row['group']].append(item)
    summaries = {}
    for group, rows in grouped.items():
        summaries[group] = {'supported_exact': sum(x['correct'] for x in rows if x['expected'] is not None), 'unsupported_STOP': sum(x['correct'] for x in rows if x['expected'] is None), 'categories': dict(collections.Counter(x['category'] for x in rows)), 'word_boundary_cuts': sum(x['cuts_word_boundary'] for x in rows), 'wrong_source_selections': sum(x['wrong_source'] for x in rows), 'supported_by_length': {str(n): {'correct': sum(x['correct'] for x in rows if x['answer_words'] == n), 'total': sum(x['answer_words'] == n for x in rows)} for n in (1, 2, 3)}}
        original = report['qualification']['groups'][group]
        assert summaries[group]['supported_exact'] == original['exact_supported']
        assert summaries[group]['unsupported_STOP'] == original['correct_stop']
    pairs = {}
    indexed = {(x['group'], x['case']): x for x in semantic}
    for first, second in [('known_source:actual', 'known_source:alternate'), ('full_corpus:actual', 'full_corpus:alternate'), ('known_source:actual', 'full_corpus:actual'), ('known_source:alternate', 'full_corpus:alternate')]:
        gains, losses, changes = [], [], []
        for identity in tasks:
            a, b = indexed[first, identity], indexed[second, identity]
            if b['correct'] and not a['correct']: gains.append(identity)
            if a['correct'] and not b['correct']: losses.append(identity)
            if a['emitted'] != b['emitted']: changes.append(identity)
        pairs[first+' -> '+second] = {'gains': gains, 'losses': losses, 'emission_changes': changes}
    window_repeats = 0
    original_rows = {(x['group'], x['case']): x for x in report['rows']}
    for wording in ('actual', 'alternate'):
        for identity, task in tasks.items():
            a = original_rows['known_source:'+wording, identity]['reading']['windows']
            b = [x for x in original_rows['full_corpus:'+wording, identity]['reading']['windows'] if decode(x['document_id_hex']) == task['expected_source_id']]
            assert len(a) == len(b)
            for left, right in zip(a, b, strict=True):
                assert {k:v for k,v in left.items() if k != 'document_index'} == {k:v for k,v in right.items() if k != 'document_index'}
                window_repeats += 1
    qualifies = all(summaries['known_source:'+w]['supported_exact'] >= 44 and summaries['known_source:'+w]['unsupported_STOP'] >= 15 for w in ('actual', 'alternate'))
    assert qualifies == report['qualification']['reader_qualifies']
    output = {'status':'saved_receipt_consistency_passed', 'artifact_sha256':digest(ARTIFACT), 'source_revision':SOURCE, 'fixture_sha256':digest(FIXTURE), 'qualification_passed':qualifies, 'rows_checked':len(semantic), 'windows_byte_and_margin_checked':windows_checked, 'repeated_expected_source_windows_exact':window_repeats, 'summaries':summaries, 'paired':pairs, 'rows':semantic, 'limits':'Saved best-per-window records cannot reconstruct unretained token logits or rank/score of a nonwinning gold span. These checks authenticate source slices and logged decoding, not independent QA inference. Categories are evaluator descriptions; no normalization credit, thresholds or new model calls.'}
    OUTPUT.write_text(json.dumps(output,indent=2)+'\n',encoding='utf-8',newline='\n')
    print(json.dumps({k:v for k,v in output.items() if k != 'rows'}))


if __name__ == '__main__':
    main()
